using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Library.Web.Models;using Library.Web.Services;
namespace Library.Web.Pages.Loans;
public sealed class IndexModel:PageModel{private readonly LibraryStore _store;public IReadOnlyList<LoanRow> Loans{get;private set;}=[];public IReadOnlyList<Book> Books{get;private set;}=[];public IReadOnlyList<Member> Members{get;private set;}=[];public string? ErrorMessage{get;private set;}[BindProperty]public int BookId{get;set;}[BindProperty]public int MemberId{get;set;}[BindProperty]public DateTime DueDate{get;set;}=DateTime.Today.AddDays(14);public IndexModel(LibraryStore store)=>_store=store;public void OnGet()=>Load();public IActionResult OnPostBorrow(){try{_store.Borrow(BookId,MemberId,DueDate);return RedirectToPage();}catch(Exception ex){ErrorMessage=ex.Message;Load();return Page();}}public IActionResult OnPostReturn(int id){try{_store.Return(id);}catch(Exception ex){ErrorMessage=ex.Message;}Load();return Page();}private void Load(){Loans=_store.Loans;Books=_store.Books;Members=_store.Members;}}
